CREATE TABLE "participant_profiles" ("id" UUID PRIMARY KEY,"user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"public_name" TEXT NOT NULL,"bio" TEXT NOT NULL DEFAULT '',"location" TEXT,"disciplines" JSONB NOT NULL DEFAULT '[]',"experience" TEXT NOT NULL DEFAULT '',"achievements" TEXT NOT NULL DEFAULT '',"avatar_file_id" UUID REFERENCES stored_files(id) ON DELETE RESTRICT ON UPDATE CASCADE,"document_file_ids" JSONB NOT NULL DEFAULT '[]',"public_link" TEXT,"visibility" TEXT NOT NULL DEFAULT 'PRIVATE',"moderation_status" TEXT NOT NULL DEFAULT 'PENDING',"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT "participant_profiles_visibility_check" CHECK ("visibility" IN ('PRIVATE','PUBLIC')),CONSTRAINT "participant_profiles_moderation_check" CHECK ("moderation_status" IN ('PENDING','PUBLISH','HIDE')));
CREATE UNIQUE INDEX "participant_profiles_user_id_key" ON "participant_profiles"("user_id");

